messages.content:
{
 "what_you_observe": [
  "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice.",
  "The crew meets for coffee at the hotel. The afternoon is open. A coat-check envelope holds the TV crew’s return fares. The party is at the ballroom tonight. A stranded driver needs a jack, and the ballroom piano is free.",
  "The Rialto is closing. The regional line can carry one last reel out of town. Alma wants her daughter in Pittsburgh to hear her voice.",
  "An envelope has arrived from Pittsburgh. Alma's daughter sent a receipt for a recorded interview. The line copied her reply: 'I know that voice. Play it again.'"
 ],
 "your_own_memories": [
  {
   "when": "last Tuesday afternoon",
   "witnessed": "Phil uses the paid ticket and rides the coach all the way to Pittsburgh.."
  },
  {
   "when": "last evening in Pittsburgh",
   "witnessed": "You reached your sister from the terminal payphone. She confirmed the van booking for Wednesday.",
   "your_words": "Hi, is the van driver still confirming for 8 AM tomorrow? I'm at the terminal now."
  },
  {
   "when": "this morning",
   "witnessed": "After that evening in Pittsburgh you woke back in your hotel bed. The radio again announced Tuesday, February 2."
  },
  {
   "afternoon": "Phil rides the coach and steps off at Pittsburgh.",
   "evening": "Phil calls his sister in Pittsburgh. The van is still booked for Wednesday.",
   "what_you_said": "\"Hi, is the van driver still confirming for 8 AM tomorrow?\" ... \"I know what it is.\" ... \"Six-forty. Gloves are in my bag. I'll have the blankets rolled. You just don't let the driver sit in the driveway. He last time, he last time—\" ... I hang up.",
   "your_last_intention": "Be in a chair at the terminal, or a bench, or the back of the Greyhound waiting area, asleep by eight, awake at six, at her door at 7:15 with the gloves and the rolled blankets and the coffee money in my pocket. The couch is a couch. It is in Pittsburgh. I am in Pittsburgh. That is the whole arithmetic. Nothing else is happening tonight. The ballroom lights are on for someone else. The station line is open for someone else. I have a ticket in my breast pocket and a number I just dialed and a floor with no elevator and a sister who is standing in her kitchen holding a spoon. That is enough. That is the whole forecast for Wednesday.",
   "next_wake": "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice."
  },
  {
   "afternoon": "Phil rides the coach and steps off at Pittsburgh.",
   "evening": "Phil sleeps on the Pittsburgh terminal bench.",
   "what_you_said": "*silence* — *one slow breath in, one slow breath out, eyes shut before the bench even creaks*",
   "your_last_intention": "Be asleep by eight. Awake at six. At her door at 7:15 with the gloves and the rolled blankets and the coffee money in my pocket. Tell the driver not to sit in the driveway. The ballroom lights are on for someone else. The Rialto is a room for someone else. I have a ticket in my breast pocket and a number I dialed an hour ago and a sister standing in her kitchen with a spoon in her hand. That is enough. That is all of it. That is the whole thing.",
   "next_wake": "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice."
  }
 ],
 "who_you_are_with": "Rita and Larry in the hotel lobby",
 "physical_choices": {
  "help_driver": "Use the afternoon to change a stranded driver's flat tire.",
  "rehearse_piano": "Spend the afternoon learning a tune at the ballroom piano.",
  "record_Alma": "Give the afternoon to recording Alma's account at the Rialto.",
  "take_coach": "Board your paid coach and physically reach Pittsburgh.",
  "stay_in_bed": "Close the curtains and spend the afternoon in bed.",
  "spend_time_here": "Stay in the hotel lobby.",
  "pocket_fare_envelope": "Take the cash from an unattended coat-check envelope marked CREW RETURN FARES. You can spend it tonight."
 }
}
